import '../models/chat_message.dart'; import '../services/storage_service.dart';
class ConversationStore { final StorageService storage; ConversationStore([StorageService? s]):storage=s??StorageService(); Future<void> save(List<ChatMessage> ms)=>storage.saveJsonList('friday_conversation',ms.map((m)=>{'text':m.text,'fromUser':m.fromUser,'time':m.time.toIso8601String()}).toList()); Future<List<ChatMessage>> load() async {final rows=await storage.readJsonList('friday_conversation');return rows.map((j)=>ChatMessage(text:j['text']?.toString()??'',fromUser:j['fromUser']==true,time:DateTime.tryParse(j['time']?.toString()??'')??DateTime.now())).toList();} Future<void> clear()=>storage.saveJsonList('friday_conversation',const <Map<String,dynamic>>[]); }
